INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45361, 'Jeremiah 50:18', 'Jeremiah', 50, 18, 'نو په دې وجه مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، زۀ به اوس د بابل بادشاه او د هغۀ مُلک له سزا ورکړم لکه څنګه چې ما د اسور بادشاه له ورکړې وه.', 'نو په دې وجه مالک خدای رب الافواج د بنی اسراییلو خدای پاک فرمایی چې، زۀ به اوس د بابل بادشاه او د هغۀ ملک له سزا ورکرم لکه چنګه چې ما د اسور بادشاه له ورکرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45362, 'Jeremiah 50:19', 'Jeremiah', 50, 19, 'زۀ به بنى اِسرائيل خپل د څرن ځائ ته واپس راولم او هغوئ به د کرمل او بسن په پټو کښې وڅريږى، او د هغوئ لوږه به د اِفرائيم او د جِلعاد په غونډو کښې معموره شى.', 'زۀ به بنی اسراییل خپل د چرن جای ته واپس راولم او هغوی به د کرمل او بسن په پتو کشې وچریزی، او د هغوی لوزه به د افراییم او د جلعاد په غوندو کشې معموره شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45363, 'Jeremiah 50:20', 'Jeremiah', 50, 20, 'په هغه ورځو کښې، مالِک خُدائ فرمائى چې، د اِسرائيل ګناهونه به ولټولے شى خو يو به په کښې پېدا نۀ شى، او د يهوداه ګناهونه به ولټولے شى او هيڅ ګناه به په کښې پېدا نۀ شى، ځکه چې کوم ما ژوندى پرېښودى دى زۀ به د هغوئ ګناهونه معاف کړم.“', 'په هغه ورجو کشې، مالک خدای فرمایی چې، د اسراییل ګناهونه به ولتولے شی خو یو به په کشې پېدا نۀ شی، او د یهوداه ګناهونه به ولتولے شی او هیچ ګناه به په کشې پېدا نۀ شی، جکه چې کوم ما ژوندی پرېشودی دی زۀ به د هغوی ګناهونه معاف کرم.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45364, 'Jeremiah 50:21', 'Jeremiah', 50, 21, 'مالِک خُدائ فرمائى، ”زما لښکرو د مراتايم په وطن او د فقود په خلقو باندې حمله وکړئ. هغوئ پسې شئ، او وې وژنئ او مکمل يې تباه کړئ، او هر څۀ وکړئ د څۀ چې ما حکم درکړے دے.', 'مالک خدای فرمایی، ”زما لشکرو د مراتایم په وطن او د فقود په خلقو باندې حمله وکری. هغوی پسې شی، او وې وژنی او مکمل یې تباه کری، او هر چۀ وکری د چۀ چې ما حکم درکرے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45365, 'Jeremiah 50:22', 'Jeremiah', 50, 22, 'په مُلک کښې دې د جنګ شور او ژړاګانې واورېدلے شى، او د لوئې تباهۍ آوازونه اورېدلے کيږى.', 'په ملک کشې دې د جنګ شور او ژراګانې واورېدلے شی، او د لویې تباهی اوازونه اورېدلے کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45366, 'Jeremiah 50:23', 'Jeremiah', 50, 23, 'په ټوله دُنيا کښې د بابل لوئ او زورَور څټک څنګه ټوکړې ټوکړې شو. او وګورئ چې بابل څنګه په نورو قومونو کښې د وحشت مثال وګرځېدو.', 'په توله دنیا کشې د بابل لوی او زورور چتک چنګه توکرې توکرې شو. او وګوری چې بابل چنګه په نورو قومونو کشې د وحشت مثال وګرجېدو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45367, 'Jeremiah 50:24', 'Jeremiah', 50, 24, 'اے بابليانو، ما تاسو ته لټ کېښودلو، خو تاسو پرې خبر نۀ وئ خو په کښې ګرفتار شوئ، ځکه چې تاسو د مالِک خُدائ خلاف جنګ وکړو.', 'اے بابلیانو، ما تاسو ته لت کېشودلو، خو تاسو پرې خبر نۀ وی خو په کشې ګرفتار شوی، جکه چې تاسو د مالک خدای خلاف جنګ وکرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45368, 'Jeremiah 50:25', 'Jeremiah', 50, 25, 'مالِک خُدائ خپل د وسلې ګودام کولاو کړے دے او د خپل غضب وسله يې ترې راويستلې ده، ځکه چې مالِک خُدائ ربُ الافواج به دا د بابل خلاف د هغوئ په مُلک کښې استعمال کړى.', 'مالک خدای خپل د وسلې ګودام کولاو کرے دے او د خپل غضب وسله یې ترې راویستلې ده، جکه چې مالک خدای رب الافواج به دا د بابل خلاف د هغوی په ملک کشې استعمال کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45369, 'Jeremiah 50:26', 'Jeremiah', 50, 26, 'د هرې خوا نه د هغۀ خلاف حمله وکړئ، او ګودامونه يې مات کړئ، او هغه لکه د غلې دانو په شان ډېرے کړئ. په مکمل توګه هغه تباه کړئ او هيڅ څوک په کښې ژوندى مۀ پرېږدئ.', 'د هرې خوا نه د هغۀ خلاف حمله وکری، او ګودامونه یې مات کری، او هغه لکه د غلې دانو په شان دېرے کری. په مکمل توګه هغه تباه کری او هیچ چوک په کشې ژوندی مۀ پرېزدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45370, 'Jeremiah 50:27', 'Jeremiah', 50, 27, 'د هغوئ ټول غوَيان حلال کړئ، په دوئ دې افسوس وى ځکه د هغوئ د سزا او حساب ورځ او وخت رارسېدلے دے.', 'د هغوی تول غویان حلال کری، په دوی دې افسوس وی جکه د هغوی د سزا او حساب ورج او وخت رارسېدلے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45371, 'Jeremiah 50:28', 'Jeremiah', 50, 28, 'هغه کسانو ته غوږ شئ څوک چې د بابل نه راتښتېدلى دى، نو هغوئ په يروشلم کښې وائى چې مالِک خُدائ زمونږ خُدائ پاک د هغوئ نه څنګه انتقام اخلى څوک چې د هغۀ کور تباه کوى.', 'هغه کسانو ته غوز شی چوک چې د بابل نه راتشتېدلی دی، نو هغوی په یروشلم کشې وایی چې مالک خدای زمونز خدای پاک د هغوی نه چنګه انتقام اخلی چوک چې د هغۀ کور تباه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45372, 'Jeremiah 50:29', 'Jeremiah', 50, 29, 'ټول لينده چلوونکى د بابل خلاف راجمع کړئ، محاصره يې کړئ چې يو کس هم درنه ونۀ تښتى. هغۀ ته د خپلو اعمالو په مطابق بدله ورکړئ، هغۀ سره هغه څۀ وکړئ کوم چې دۀ د نورو خلقو سره کړى دى. ځکه چې بابل د خپلې مغرورتيا په وجه د مالِک خُدائ د بنى اِسرائيلو د مقدس ذات خلاف سرکشى کړې ده.', 'تول لینده چلوونکی د بابل خلاف راجمع کری، محاصره یې کری چې یو کس هم درنه ونۀ تشتی. هغۀ ته د خپلو اعمالو په مطابق بدله ورکری، هغۀ سره هغه چۀ وکری کوم چې دۀ د نورو خلقو سره کری دی. جکه چې بابل د خپلې مغرورتیا په وجه د مالک خدای د بنی اسراییلو د مقدس ذات خلاف سرکشی کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45373, 'Jeremiah 50:30', 'Jeremiah', 50, 30, 'مالِک خُدائ فرمائى چې، د هغۀ ځوانان به په کوڅو کښې راپرېوځى او قتل به شى، او د هغوئ فوجيان به په هغه ورځ ټول ختم کړے شى.', 'مالک خدای فرمایی چې، د هغۀ جوانان به په کوچو کشې راپرېوجی او قتل به شی، او د هغوی فوجیان به په هغه ورج تول ختم کرے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45374, 'Jeremiah 50:31', 'Jeremiah', 50, 31, 'مالِک خُدائ ربُ الافواج فرمائى چې، ګورئ، زۀ ستاسو خلاف يم، اے مغروره خلقو، ستاسو د سزا ورځ رارسېدلې ده هغه وخت چې زۀ تاسو له سزا درکړم.', 'مالک خدای رب الافواج فرمایی چې، ګوری، زۀ ستاسو خلاف یم، اے مغروره خلقو، ستاسو د سزا ورج رارسېدلې ده هغه وخت چې زۀ تاسو له سزا درکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45375, 'Jeremiah 50:32', 'Jeremiah', 50, 32, 'ستا کبرژن قوم به تيندک وخورى او راوبه غورزيږى، او هيڅ څوک به تاسو نۀ راوچتوى، زۀ به د هغۀ په ښارونو اور بل کړم او هغه به په خپل شا او خوا کښې ځان سره هر څۀ وسوزوى.', 'ستا کبرژن قوم به تیندک وخوری او راوبه غورزیزی، او هیچ چوک به تاسو نۀ راوچتوی، زۀ به د هغۀ په شارونو اور بل کرم او هغه به په خپل شا او خوا کشې جان سره هر چۀ وسوزوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45376, 'Jeremiah 50:33', 'Jeremiah', 50, 33, 'مالِک خُدائ ربُ الافواج فرمائى چې، د اِسرائيل او د يهوداه خلق مظلومان دى، هغوئ چې چا نيولى دى نو د هغوئ د پرېښودو نه اِنکار کوى.', 'مالک خدای رب الافواج فرمایی چې، د اسراییل او د یهوداه خلق مظلومان دی، هغوی چې چا نیولی دی نو د هغوی د پرېشودو نه انکار کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45377, 'Jeremiah 50:34', 'Jeremiah', 50, 34, 'خو د هغوئ بچ کوونکے ډېر زورَور دے، او مالِک خُدائ ربُ الافواج د هغۀ نوم دے. هغه به په سختۍ سره د هغوئ د مسئلې دفاع وکړى، او هغه به دوئ ته آرام ورکړى، خو د بابل خلق به نا آرامه کړى.', 'خو د هغوی بچ کوونکے دېر زورور دے، او مالک خدای رب الافواج د هغۀ نوم دے. هغه به په سختی سره د هغوی د مسیلې دفاع وکری، او هغه به دوی ته ارام ورکری، خو د بابل خلق به نا ارامه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45378, 'Jeremiah 50:35', 'Jeremiah', 50, 35, 'مالِک خُدائ فرمائى چې، د تباهۍ تُوره دې بابل تباه کړى. هغه دې د بابل ټول اوسېدونکى او د هغۀ آفسران او هوښياران خلق تباه کړى.', 'مالک خدای فرمایی چې، د تباهی توره دې بابل تباه کری. هغه دې د بابل تول اوسېدونکی او د هغۀ افسران او هوشیاران خلق تباه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45379, 'Jeremiah 50:36', 'Jeremiah', 50, 36, 'د هغوئ دروغژن نبيان به په جنګ کښې مړۀ شى، او هغوئ به بې‌وقوفان ثابت شى. د هغوئ تکړه فوجيان به په جنګ کښې قتل کړے شى، او هغوئ به سختو يرو ترخو کښې راګېر شى.', 'د هغوی دروغژن نبیان به په جنګ کشې مرۀ شی، او هغوی به بې‌وقوفان ثابت شی. د هغوی تکره فوجیان به په جنګ کشې قتل کرے شی، او هغوی به سختو یرو ترخو کشې راګېر شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45380, 'Jeremiah 50:37', 'Jeremiah', 50, 37, 'جنګ به د هغوئ خلاف د هغوئ آسونه او جنګى ګاډۍ تباه کړى او په هغۀ کښې د نورو مُلکونو فوجيان به هم تباه کړى. او هغوئ به د ښځو په شان بُزدله شى. او جنګ به د هغوئ خزانې تباه کړى، او لوټ به يې کړى.', 'جنګ به د هغوی خلاف د هغوی اسونه او جنګی ګادی تباه کری او په هغۀ کشې د نورو ملکونو فوجیان به هم تباه کری. او هغوی به د شجو په شان بزدله شی. او جنګ به د هغوی خزانې تباه کری، او لوت به یې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45381, 'Jeremiah 50:38', 'Jeremiah', 50, 38, 'د هغۀ د اوبو ذخيرې دې اوچې کړے شى. هغه به اوچې شى، ځکه چې ټول مُلک د بُتانو نه ډک شوے دے، او د هغه خلقو د بُتانو د يرې نه لکه د ليونو په شان عمل وکړو.', 'د هغۀ د اوبو ذخیرې دې اوچې کرے شی. هغه به اوچې شی، جکه چې تول ملک د بتانو نه دک شوے دے، او د هغه خلقو د بتانو د یرې نه لکه د لیونو په شان عمل وکرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45382, 'Jeremiah 50:39', 'Jeremiah', 50, 39, 'نو بيا به په بابل کښې د دشتو ځناور اوسيږى، او د ګيدړانو او ګونګيانو په کور به بدل شى. نو دا به بيا هيڅکله آباد نۀ شى او دا به همېشه دپاره شاړ پروت وى.', 'نو بیا به په بابل کشې د دشتو جناور اوسیزی، او د ګیدرانو او ګونګیانو په کور به بدل شی. نو دا به بیا هیچکله اباد نۀ شی او دا به همېشه دپاره شار پروت وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45383, 'Jeremiah 50:40', 'Jeremiah', 50, 40, 'لکه څنګه چې خُدائ پاک سدوم او عموره، سره د ګاونډيانو تباه کړل هم هغه شان به بابل هم تباه کړى. مالِک خُدائ فرمائى چې، نو هيڅ څوک به هلته نۀ اوسيږى او نۀ به يو انسان په کښې ژوند کوى.', 'لکه چنګه چې خدای پاک سدوم او عموره، سره د ګاوندیانو تباه کرل هم هغه شان به بابل هم تباه کری. مالک خدای فرمایی چې، نو هیچ چوک به هلته نۀ اوسیزی او نۀ به یو انسان په کشې ژوند کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_40.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45384, 'Jeremiah 50:41', 'Jeremiah', 50, 41, 'وګورئ، د شمال د خوا نه فوج راروان دے، يو لوئ قوم او ډېر بادشاهان د دُنيا د آخر نه راپاڅېدلى دى.', 'وګوری، د شمال د خوا نه فوج راروان دے، یو لوی قوم او دېر بادشاهان د دنیا د اخر نه راپاچېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_41.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45385, 'Jeremiah 50:42', 'Jeremiah', 50, 42, 'هغوئ په ليندو او نېزو باندې سمبال دى، او هغوئ ظالمان دى او هيڅ رحم په کښې نشته. کله چې هغوئ په خپلو آسونو باندې سوارۀ شى لکه د سمندر داسې غړمبار کوى، هغوئ جنګ ته په قطارونو کښې راروان دى چې په لور بابل باندې حمله وکړى.', 'هغوی په لیندو او نېزو باندې سمبال دی، او هغوی ظالمان دی او هیچ رحم په کشې نشته. کله چې هغوی په خپلو اسونو باندې سوارۀ شی لکه د سمندر داسې غرمبار کوی، هغوی جنګ ته په قطارونو کشې راروان دی چې په لور بابل باندې حمله وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_42.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45386, 'Jeremiah 50:43', 'Jeremiah', 50, 43, 'د بابل بادشاه چې د دشمن د راتلو په حقله دا خبر واورېدو، نو د هغۀ لاسونه شل شول. هغه يرې او دردونو ونيولو، داسې درد لکه چې د ښځې د لنګون په وخت کښې وى.', 'د بابل بادشاه چې د دشمن د راتلو په حقله دا خبر واورېدو، نو د هغۀ لاسونه شل شول. هغه یرې او دردونو ونیولو، داسې درد لکه چې د شجې د لنګون په وخت کشې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45387, 'Jeremiah 50:44', 'Jeremiah', 50, 44, 'لکه څنګه چې يو زمرے د اُردن د جاړو بوټو نه د څرن زمکې ته راځى او په ګډو ورټوپ کوى، نو دغه شان به زۀ د بابل خلق د خپل مُلک نه وشړم، او زۀ به د خپلې خوښى مشر په کښې مقرر کړم. نو هغه به په دوئ حکومت وکړى. څوک زما په شان کېدلے شى؟ او يو مشر به هم زما خلاف ونۀ دريږى.', 'لکه چنګه چې یو زمرے د اردن د جارو بوتو نه د چرن زمکې ته راجی او په ګدو ورتوپ کوی، نو دغه شان به زۀ د بابل خلق د خپل ملک نه وشرم، او زۀ به د خپلې خوشی مشر په کشې مقرر کرم. نو هغه به په دوی حکومت وکری. چوک زما په شان کېدلے شی؟ او یو مشر به هم زما خلاف ونۀ دریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_44.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45388, 'Jeremiah 50:45', 'Jeremiah', 50, 45, 'نو بيا هغې منصوبې ته غوږ شه کومه چې مالِک خُدائ د بابليانو خلاف جوړه کړې ده، تر دې چې واړۀ ماشومان به د ګډورو په شان وشړلے شى، او د هغوئ د څرن ځايونه به وران کړے شى.', 'نو بیا هغې منصوبې ته غوز شه کومه چې مالک خدای د بابلیانو خلاف جوره کرې ده، تر دې چې وارۀ ماشومان به د ګدورو په شان وشرلے شی، او د هغوی د چرن جایونه به وران کرے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_45.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45389, 'Jeremiah 50:46', 'Jeremiah', 50, 46, 'زمکه به په دې چغو سورو سره په لړزان شى ”بابل قبضه کړے شوے دے.“ او د هغوئ د مايوسۍ ژړا به په ټوله دُنيا کښې واورېدلے شى.“', 'زمکه به په دې چغو سورو سره په لرزان شی ”بابل قبضه کرے شوے دے.“ او د هغوی د مایوسی ژرا به په توله دنیا کشې واورېدلے شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_50_46.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
