(45422, 'Numbers 19:2', 'Numbers', 19, 2, '«د اسراییلو قوم باید موسی ته یوه داسې سره غوا راولي چې کوم عیب په کې نه وي او هېڅکله ورباندې قلبه نه وي شوې.', '«د اسراییلو قوم باید موسی ته یوه داسې سره غوا راولی چې کوم عیب په کې نه وی او هېچکله ورباندې قلبه نه وی شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45423, 'Numbers 19:3', 'Numbers', 19, 3, 'هغوی به هغه العازار کاهن ته ورکړي، بیا به هغه د کمپ څخه دباندې وویستل شي او د هغه په حضور کې به حلاله شي.', 'هغوی به هغه العازار کاهن ته ورکری، بیا به هغه د کمپ چخه دباندې وویستل شی او د هغه په حضور کې به حلاله شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45424, 'Numbers 19:4', 'Numbers', 19, 4, 'بیا به العازار د هغې څخه لږه وینه واخلي او په خپله ګوته باندې دې اووه ځلې د سپېڅلې خېمې مخې ته وشیندي.', 'بیا به العازار د هغې چخه لزه وینه واخلی او په خپله ګوته باندې دې اووه جلې د سپېچلې خېمې مخې ته وشیندی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45425, 'Numbers 19:5', 'Numbers', 19, 5, 'بیا ټوله غوا باید د پوستکي، غوښې، وینې او کولمو سره د هغه په مخکې وسوځول شي.', 'بیا توله غوا باید د پوستکی، غوشې، وینې او کولمو سره د هغه په مخکې وسوجول شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45426, 'Numbers 19:6', 'Numbers', 19, 6, 'کاهن دې د سبر د ونې لږ لرګي، د وېلني بوټی او سور تار په اور کې واچوي.', 'کاهن دې د سبر د ونې لز لرګی، د وېلنی بوتی او سور تار په اور کې واچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45427, 'Numbers 19:7', 'Numbers', 19, 7, 'د مراسمو څخه وروسته دې کاهن خپل کالي ووینځي او غسل دې وکړي. بیا هغه کولای شي چې بېرته کمپ ته ننوځي، خو تر ماښامه پورې به ناپاک پاتې شي.', 'د مراسمو چخه وروسته دې کاهن خپل کالی ووینجی او غسل دې وکری. بیا هغه کولای شی چې بېرته کمپ ته ننوجی، خو تر ماشامه پورې به ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45428, 'Numbers 19:8', 'Numbers', 19, 8, 'هغه سړی چې غوا یې سوځولې وي هم باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به هم تر ماښامه پورې ناپاک پاتې شي.', 'هغه سری چې غوا یې سوجولې وی هم باید خپل کالی ووینجی او غسل دې وکری، خو هغه به هم تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45429, 'Numbers 19:9', 'Numbers', 19, 9, 'یو سړی چې ناپاک نه وي د سوځېدل شوې غوا ایرې دې واخلي او د کمپ څخه دباندې دې په یو پاک ځای کې واچوي. د اسراییلو قوم کولای شي چې دا ایرې د هغو اوبو سره ګډې کړي چې د ګناه د پاکولو په مراسمو کې ورڅخه کار اخیستل کیږي.', 'یو سری چې ناپاک نه وی د سوجېدل شوې غوا ایرې دې واخلی او د کمپ چخه دباندې دې په یو پاک جای کې واچوی. د اسراییلو قوم کولای شی چې دا ایرې د هغو اوبو سره ګدې کری چې د ګناه د پاکولو په مراسمو کې ورچخه کار اخیستل کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45430, 'Numbers 19:10', 'Numbers', 19, 10, 'هغه سړی چې ایرې راټولوي باید خپل کالي ووینځي، خو تر ماښامه پورې به ناپاک پاتې شي. د اسراییلو قوم او هغه پردي خلک چې د دوی په منځ کې اوسیږي، باید تل د دې قانون اطاعت وکړي.', 'هغه سری چې ایرې راتولوی باید خپل کالی ووینجی، خو تر ماشامه پورې به ناپاک پاتې شی. د اسراییلو قوم او هغه پردی خلک چې د دوی په منج کې اوسیزی، باید تل د دې قانون اطاعت وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45431, 'Numbers 19:11', 'Numbers', 19, 11, 'که چېرې څوک یو مړي ته لاس وروړي، اووه ورځې به ناپاک وي.', 'که چېرې چوک یو مری ته لاس وروری، اووه ورجې به ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45432, 'Numbers 19:12', 'Numbers', 19, 12, 'خو که چېرې په درېمه ورځ او بیا په اوومه ورځ په هغو اوبو باندې چې د غوا ایرې ورسره ګډې وي خپل ځان پاک کړي، هغه به پاک شي. که په هغو ورځو کې خپل ځان پاک نه کړي، نو ناپاک به پاتې شي.', 'خو که چېرې په درېمه ورج او بیا په اوومه ورج په هغو اوبو باندې چې د غوا ایرې ورسره ګدې وی خپل جان پاک کری، هغه به پاک شی. که په هغو ورجو کې خپل جان پاک نه کری، نو ناپاک به پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45433, 'Numbers 19:13', 'Numbers', 19, 13, 'که چېرې څوک مړي ته لاس وروړي او خپل ځان پاک نه کړي هغه ناپاکه پاتې کیږي، ځکه چې د پاکوالي اوبه ورباندې نه دي اچول شوې. هغه کس سپېڅلې خېمه ناپاکه کړې ده او د اسراییلو د قوم څخه باید وشړل شي.', 'که چېرې چوک مری ته لاس وروری او خپل جان پاک نه کری هغه ناپاکه پاتې کیزی، جکه چې د پاکوالی اوبه ورباندې نه دی اچول شوې. هغه کس سپېچلې خېمه ناپاکه کرې ده او د اسراییلو د قوم چخه باید وشرل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45434, 'Numbers 19:14', 'Numbers', 19, 14, 'په هغه حالت کې چې یو کس په خېمه کې مړ شي، نو هغه څوک چې د هغه کس د مرګ په وخت کې په خېمه کې وي یا څوک چې خېمې ته ورننوځي هغه به اووه ورځې ناپاک وي.', 'په هغه حالت کې چې یو کس په خېمه کې مر شی، نو هغه چوک چې د هغه کس د مرګ په وخت کې په خېمه کې وی یا چوک چې خېمې ته ورننوجی هغه به اووه ورجې ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45435, 'Numbers 19:15', 'Numbers', 19, 15, 'هر منګی او لوښی چې په خېمه کې وي او سرپوښ ونه لري، هغه ناپاک کیږي.', 'هر منګی او لوشی چې په خېمه کې وی او سرپوش ونه لری، هغه ناپاک کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45436, 'Numbers 19:16', 'Numbers', 19, 16, 'که چېرې څوک د یو داسې کس مړي ته لاس وروړي چې د کور څخه دباندې په وسله باندې وژل شوی وي یا په خپل مرګ مړ شوی وي یا که چېرې د انسان هډوکي یا قبر ته لاس وروړي، هغه به اووه ورځې ناپاک وي.', 'که چېرې چوک د یو داسې کس مری ته لاس وروری چې د کور چخه دباندې په وسله باندې وژل شوی وی یا په خپل مرګ مر شوی وی یا که چېرې د انسان هدوکی یا قبر ته لاس وروری، هغه به اووه ورجې ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45437, 'Numbers 19:19', 'Numbers', 19, 19, 'هغه کس چې پاک وي، په ناپاکه کس باندې دې په درېمه او اوومه ورځ هغه اوبه وشیندي. په اوومه ورځ هغه کس چې پاکیږي باید خپل کالي ووینځي او غسل دې وکړي، نو ماښام به هغه پاک شي.', 'هغه کس چې پاک وی، په ناپاکه کس باندې دې په درېمه او اوومه ورج هغه اوبه وشیندی. په اوومه ورج هغه کس چې پاکیزی باید خپل کالی ووینجی او غسل دې وکری، نو ماشام به هغه پاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45438, 'Numbers 19:20', 'Numbers', 19, 20, 'که چېرې یو کس په مذهبي لحاظ ناپاک وي او خپل ځان پاک نه کړي هغه ناپاک پاتې کیږي، ځکه چې په هغه باندې د پاکوالي اوبه نه دي اچول شوې. هغه سپېڅلې خېمه ناپاکه کړې ده او د اسراییلو د قوم څخه باید وشړل شي.', 'که چېرې یو کس په مذهبی لحاظ ناپاک وی او خپل جان پاک نه کری هغه ناپاک پاتې کیزی، جکه چې په هغه باندې د پاکوالی اوبه نه دی اچول شوې. هغه سپېچلې خېمه ناپاکه کرې ده او د اسراییلو د قوم چخه باید وشرل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45439, 'Numbers 19:21', 'Numbers', 19, 21, 'دا قوانین به هېڅکله بدل نه شي. کوم کس چې د پاکوالي په خاطر هغه اوبه شیندي باید خپل کالي هم ووینځي. که څوک دې اوبو ته لاس وروړي هغه به تر ماښامه پورې ناپاک وي.', 'دا قوانین به هېچکله بدل نه شی. کوم کس چې د پاکوالی په خاطر هغه اوبه شیندی باید خپل کالی هم ووینجی. که چوک دې اوبو ته لاس وروری هغه به تر ماشامه پورې ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45440, 'Numbers 19:22', 'Numbers', 19, 22, 'یو ناپاک کس چې هر شي ته لاس وروړي هغه شی به ناپاک شي او که بل کس هغه شي ته لاس وروړي، هغه به هم تر ماښامه پورې ناپاک وي.»', 'یو ناپاک کس چې هر شی ته لاس وروری هغه شی به ناپاک شی او که بل کس هغه شی ته لاس وروری، هغه به هم تر ماشامه پورې ناپاک وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_19_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45441, 'Psalms 32:1', 'Psalms', 32, 1, 'بختور دی هغه څوک چې سرکښي یې بخښل شوې هغه څوک چې په ګناهونو یې اچول شوې پرده', 'بختور دی هغه چوک چې سرکشی یې بخشل شوې هغه چوک چې په ګناهونو یې اچول شوې پرده', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_32_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45442, 'Psalms 32:2', 'Psalms', 32, 2, 'بختور دی هغه څوک چې څښتن یې نه ګڼي مجرم او هغه څوک چې د ټګۍ نه پاک وي', 'بختور دی هغه چوک چې چشتن یې نه ګنی مجرم او هغه چوک چې د تګی نه پاک وی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_32_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45443, 'Psalms 32:3', 'Psalms', 32, 3, 'کله چې نه مې کاوه اقرار په ګناهونو خپلو نو ټوله ورځ به له زګېروو نه زه ستومانه ومه', 'کله چې نه مې کاوه اقرار په ګناهونو خپلو نو توله ورج به له زګېروو نه زه ستومانه ومه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_32_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45444, 'Psalms 32:4', 'Psalms', 32, 4, 'راکوله به سزا راته شپه او ورځ تا ای څښتنه ما قوت خپل بیخي ورکړ له لاسه لکه څنګه چې د اوړي ګرمي وچ کړي لنده بل', 'راکوله به سزا راته شپه او ورج تا ای چشتنه ما قوت خپل بیخی ورکر له لاسه لکه چنګه چې د اوری ګرمی وچ کری لنده بل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_32_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45445, 'Psalms 32:5', 'Psalms', 32, 5, 'نو ما تاته اقرار وکړلو د خپلو ګناهونو پټ مې نه کړل ما له تا نه خپل جرمونه دا مې وویل د خپل ځان سره په زړه کې: «زه به په خپلو سرکښیو باندې وکړمه اقرار څښتن ته» او تا زما ټول ګناهونه معاف کړل', 'نو ما تاته اقرار وکرلو د خپلو ګناهونو پت مې نه کرل ما له تا نه خپل جرمونه دا مې وویل د خپل جان سره په زره کې: «زه به په خپلو سرکشیو باندې وکرمه اقرار چشتن ته» او تا زما تول ګناهونه معاف کرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_32_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
